        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var font=new Font("Microsoft YaHei UI",9))using(var textBrush=new SolidBrush(Theme.Muted))foreach(int row in new[]{0,1}){var values=row==0?Source:Result;int top=25+row*Height/2,center=top+Height/5;e.Graphics.DrawString(row==0?"原声片段":"处理后片段",font,textBrush,12,top-20);using(var pen=new Pen(row==0?Theme.Blue:Color.FromArgb(45,184,139),1.3F)){e.Graphics.DrawLine(Pens.LightGray,12,center,Width-12,center);for(int i=0;i<values.Length;i++){float x=12+(Width-24F)*i/Math.Max(1,values.Length-1),h=values[i]*Height/5;e.Graphics.DrawLine(pen,x,center-h,x,center+h);}}}}
    }
