void BuildOptions(){options.SuspendLayout();options.Controls.Clear();var heading=Label("处理选项");options.Controls.Add(heading);options.SetFlowBreak(heading,true);options.Controls.AddRange(new Control[]{Label("输出格式"),format,Label("质量"),quality});options.SetFlowBreak(quality,true);options.Controls.AddRange(new Control[]{Label("采样率"),rate,Label("声道"),channels});options.SetFlowBreak(channels,true);if(mode=="背景降噪"){options.Controls.AddRange(new Control[]{Label("降噪强度"),strength,hum});options.SetFlowBreak(hum,true);}var hint=Label(mode=="背景降噪"?"适合底噪、风扇声、嘶声；不能保证去除说话声、音乐或突发声。先试听，再整段处理。":"有损转无损不能恢复丢失音质；WAV/AIFF/CAF/AU/W64 为 16-bit PCM。特殊格式会自动适配采样率/声道。");hint.Tag="hint";hint.MaximumSize=new Size(Math.Max(120,options.ClientSize.Width-35),0);options.Controls.Add(hint);options.ResumeLayout();}
        void Queue(Func<CancellationToken,Task> action){if(Busy)return;operation=RunAction(action);}
        async Task RunAction(Func<CancellationToken,Task> action)
        {
            cancellation=new CancellationTokenSource();SetBusy();StopPlayback();try{await action(cancellation.Token);}catch(OperationCanceledException){status.Text="已取消，已完成结果仍可下载。";}catch(Exception error){status.Text=error.Message;MessageBox.Show(this,error.Message,"音频处理提示",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{if(clipFolder!=null&&sampleContext=="")CleanupClip();cancellation.Dispose();cancellation=null;progress.Indeterminate=false;SetBusy();RefreshResult();}
        }
        void SetBusy(){foreach(var command in commands)command.Enabled=!Busy;options.Enabled=!Busy;start.Enabled=true;start.Text=Busy?"取消当前操作":mode=="背景降噪"?"开始降噪":"开始转换";download.Enabled=!Busy;if(BusyChanged!=null)BusyChanged();}
        async Task Initialize(CancellationToken token){initializing=true;try{status.Text="正在读取本地音频引擎…";progress.Indeterminate=true;var formats=await Task.Run(()=>engine.Formats(token));foreach(var item in formats)format.Items.Add(item);format.SelectedIndex=0;ready=true;status.Text="音频引擎就绪，可输出 "+formats.Length+" 种格式组合。";}finally{initializing=false;}}
        void QueueAdd(string[] paths){Queue(async token=>{if(!ready)await Initialize(token);int skipped=0;foreach(string raw in paths){token.ThrowIfCancellationRequested();string path=Path.GetFullPath(raw);if(files.Any(f=>f.Path.Equals(path,StringComparison.OrdinalIgnoreCase)))continue;status.Text="正在检查 "+Path.GetFileName(path);try{var info=await Task.Run(()=>engine.Inspect(path,token));files.Add(info);cards.Items.Add(new InputFile(path));}catch(IOException){skipped++;}}cards.SelectedIndex=files.Count-1;cards.RefreshLayout();Select();status.Text="已添加 "+files.Count+" 个文件"+(skipped>0?"，跳过 "+skipped+" 个无法识别的输入。":"。");});}
        new void Move(int delta){if(Busy)return;int i=cards.SelectedIndex,j=i+delta;if(i<0||j<0||j>=files.Count)return;var info=files[i];files[i]=files[j];files[j]=info;var card=cards.Items[i];cards.Items[i]=cards.Items[j];cards.Items[j]=card;cards.SelectedIndex=j;cards.Invalidate();RefreshResult();}
        void Remove(int index){if(Busy||index<0||index>=files.Count)return;files.RemoveAt(index);cards.Items.RemoveAt(index);cards.SelectedIndex=Math.Min(index,files.Count-1);cards.RefreshLayout();Select();RefreshResult();}
        new void Select(){InvalidateSample();var file=Selected;detail.Text=file==null?"选择音频，查看信息并生成试听片段。":Path.GetFileName(file.Path)+"\r\n"+file.Codec+" · "+file.Rate+" Hz · "+file.Channels+" 声道\r\n"+TimeSpan.FromSeconds(Math.Max(0,file.Duration)).ToString(@"hh\:mm\:ss")+" · "+DownloadJob.SizeText(file.Length);clipStart.Maximum=file==null?0:Math.Max(0,(decimal)Math.Floor(file.Duration-0.1));clipStart.Value=0;}
        void InvalidateSample(){StopPlayback();sampleContext="";sourceClip=resultClip=null;wave.Source=wave.Result=new float[0];wave.Invalidate();playSource.Enabled=playResult.Enabled=false;}
        void RefreshResult(){var result=outcomes.Get(mode);download.Visible=result!=null&&result.Files.Length>0;download.Text=outcomes.Matches(mode,Context)?"↓  下载处理结果":"↓  下载上次结果（输入或选项已改变）";if(!Busy){start.Text=mode=="背景降噪"?"开始降噪":"开始转换";start.Enabled=ready&&files.Count>0;sample.Enabled=ready&&Selected!=null;playSource.Enabled=playResult.Enabled=sourceClip!=null&&sampleContext==SampleKey;}}
        string SampleKey{get{return Context+"|"+(Selected==null?"":Selected.Identity)+"|"+clipStart.Value;}}
        async Task GenerateSample(CancellationToken token)
        {
            var info=Selected;if(info==null)return;if(clipStart.Value>=(decimal)info.Duration&&info.Duration>0)throw new IOException("试听起点必须早于音频结束。");CleanupClip();clipFolder=Path.Combine(Path.GetTempPath(),"LocalConverterAudio-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(clipFolder);var options=Snapshot();string key=SampleKey;double offset=(double)clipStart.Value;progress.Indeterminate=true;status.Text="正在生成原声和处理后的 15 秒试听…";
            var plain=new AudioOptions{Format=options.Format};sourceClip=await Task.Run(()=>engine.ConvertFile(info,clipFolder,plain,token,(p,s)=>{},offset,15,true));string encoded=await Task.Run(()=>engine.ConvertFile(info,clipFolder,options,token,(p,s)=>{},offset,15));var encodedInfo=await Task.Run(()=>engine.Inspect(encoded,token));resultClip=await Task.Run(()=>engine.ConvertFile(encodedInfo,clipFolder,plain,token,(p,s)=>{},0,15,true));var sourceWave=await Task.Run(()=>AudioEngine.Wave(sourceClip));var resultWave=await Task.Run(()=>AudioEngine.Wave(resultClip));wave.Source=sourceWave;wave.Result=resultWave;wave.Invalidate();sampleContext=key;status.Text="试听已就绪：同一起点、最长 15 秒，可对比原声与处理后。";
        }
        async Task Process(CancellationToken token)
        {
            if(files.Count==0)return;var old=outcomes.Get(mode);if(old!=null&&!old.Downloaded&&old.Files.Length>0&&MessageBox.Show(this,"重新处理会清除本功能未下载结果，是否继续？","音频处理",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;var options=Snapshot();var inputs=files.ToArray();var result=new ResultSession();outcomes.Set(mode,result,Context);download.Visible=false;progress.Value=0;bool active=true;var reporter=new Progress<Tuple<int,string>>(p=>{if(active&&!IsDisposed){progress.Value=p.Item1;status.Text=p.Item2;}});
            try{await Task.Run(()=>{for(int i=0;i<inputs.Length;i++){int number=i;token.ThrowIfCancellationRequested();engine.ConvertFile(inputs[i],result.Folder,options,token,(p,s)=>((IProgress<Tuple<int,string>>)reporter).Report(Tuple.Create((number*100+p)/inputs.Length,s)));}},token);status.Text="已完成 "+result.Files.Length+" 份结果，点击下方下载。";progress.Value=100;}finally{active=false;}
        }
        void QueueDownload()
        {
            if(Busy)return;var result=outcomes.Get(mode);if(result==null||result.Files.Length==0)return;string folder,name=null;var files=result.Files;
            if(files.Length==1){using(var dialog=new SaveFileDialog{Title="下载音频到…（同名自动编号）",FileName=Path.GetFileName(files[0]),Filter="音频文件|*"+Path.GetExtension(files[0]),OverwritePrompt=false,InitialDirectory=settings.OutputFolder}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;folder=Path.GetDirectoryName(dialog.FileName);name=Path.GetFileNameWithoutExtension(dialog.FileName);}}else using(var dialog=new FolderBrowserDialog{Description="选择批量音频的保存位置",SelectedPath=settings.OutputFolder}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;folder=dialog.SelectedPath;}
            Queue(async token=>{bool active=true;progress.Indeterminate=true;status.Text="正在准备下载…";var reporter=new Progress<DownloadUpdate>(p=>{if(!active||IsDisposed)return;progress.Indeterminate=p.Phase==SavePhase.Flushing;progress.Value=p.Percent;download.Text=p.Phase==SavePhase.Flushing?"正在完成保存…":"正在下载 · "+p.Percent+"% · "+DownloadJob.SizeText(p.Written)+" / "+DownloadJob.SizeText(p.Total);status.Text=p.FileIndex+" / "+p.FileCount+" · "+DownloadJob.SizeText(p.BytesPerSecond)+"/s · "+p.FileName;});try{await Task.Run(()=>DownloadJob.Save(files,folder,name,token,p=>((IProgress<DownloadUpdate>)reporter).Report(p)));active=false;result.Downloaded=true;progress.Value=100;status.Text="已下载 "+files.Length+" 份音频到 "+folder;settings.OutputFolder=folder;try{settings.Save();}catch(IOException){}catch(UnauthorizedAccessException){}}finally{active=false;}});
        }
        void Play(bool processed){if(Busy||sourceClip==null||sampleContext!=SampleKey)return;StopPlayback();player=new SoundPlayer(processed?resultClip:sourceClip);player.Play();status.Text=processed?"正在播放处理后片段（最长 15 秒）":"正在播放原声片段（最长 15 秒）";}
        public void StopPlayback(){if(speech!=null)speech.StopPlayback();if(player!=null){player.Stop();player.Dispose();player=null;}}
        void CleanupClip(){StopPlayback();if(clipFolder!=null){try{Directory.Delete(clipFolder,true);}catch(IOException){}catch(UnauthorizedAccessException){}clipFolder=null;}sourceClip=resultClip=null;}
        public async Task StopAsync(){StopPlayback();if(cancellation!=null)cancellation.Cancel();if(speech!=null)await speech.StopAsync();await operation;}
        protected override void Dispose(bool disposing){if(disposing){CleanupClip();outcomes.Dispose();}base.Dispose(disposing);}
    }
